-- 2026-10-19 (owner: "fix the Alberta legal fields"; DECISIONS "2026-10-19 — Province legal details"). Additive only.
--
-- What a province or territory asks of each business structure in the onboarding Business step is region data, like
-- its holidays, privacy law and age rules: code never names a province. docs/spec/legal-details.schema.json keeps the
-- shape of each structure (generic keys: provincial_registry_number, extra_provincial_registration_number,
-- attorney_for_service.address_in_province, …, and the federal identifiers: CRA business number, Corporations Canada
-- number, CRA charity number); a row here says, for one province and one structure:
--   registry_i18n            the registry that holds the record (en, fr)
--   registry_url             its official page
--   law_i18n                 the act(s) the structure is formed or registered under (en, fr)
--   trade_name_registration  required = a sole proprietor trading under another name must register it there
--                            (the Business step asks for the registration # then); optional = no such registry
--   fields                   overlays on the schema's fields, by key: label / help (en, fr), example, pattern +
--                            pattern_message (en, fr), required (true / false) or required_when
--                            ({field, in | not_in}: required only when that field's value is, or is not, one of them)
--   source                   the official pages the row was checked against
--   verified / unverified    verified = every item was confirmed on an official government page; otherwise
--                            unverified lists what was not: registry | law | identifier | format | attorney.
--                            A format that is not verified has no pattern (the api accepts any text there).
-- The api merges the schema and these rows into the definition it serves to the Studio and validates against
-- (merchants.application.LegalForms). A province with no row for a structure gets the schema's generic fields.
--
-- SOURCES (2026-10-19): the government hosts do not resolve from the build machine, so each fact was checked against
-- the official page's text as a web search returned it (the page URLs are in `source`). French names of registries
-- and statutes that have no official French version are our translations of the descriptive part only.
CREATE TABLE region.legal_forms (
  province                text        NOT NULL CHECK (province ~ '^[A-Z]{2}$'),
  structure               text        NOT NULL CHECK (structure IN ('sole', 'partnership', 'corp_prov', 'corp_fed', 'corp_ex', 'coop', 'nonprofit')),
  registry_i18n           jsonb       NOT NULL CHECK (registry_i18n ? 'en' AND registry_i18n ? 'fr'),
  registry_url            text        CHECK (registry_url IS NULL OR registry_url ~ '^https://'),
  law_i18n                jsonb       NOT NULL CHECK (law_i18n ? 'en' AND law_i18n ? 'fr'),
  trade_name_registration text        NOT NULL DEFAULT 'required' CHECK (trade_name_registration IN ('required', 'optional')),
  fields                  jsonb       NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(fields) = 'object'),
  source                  text        NOT NULL CHECK (char_length(btrim(source)) BETWEEN 1 AND 600),
  verified                boolean     NOT NULL DEFAULT false,
  unverified              text[]      NOT NULL DEFAULT '{}',
  updated_at              timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (province, structure),
  CONSTRAINT chk_legal_forms_verified CHECK (verified = (cardinality(unverified) = 0))
);
COMMENT ON TABLE region.legal_forms IS
  'Per province and business structure: registry, governing act, provincial identifiers (labels, formats, help) of the onboarding legal details (V372)';

